import { Spacer } from '@/components/Elements/Spacer'
import Title from '@/components/Elements/Title'
// @ts-ignore
import AnimatedNumber from '@/components/Elements/Animated/AnimatedNumber'
// @ts-ignore
import Einwohner from '@/assets/data/einwohner.csv'

interface InputDataType {
  year: string
  einwohnerAmount: number
}
interface CsvRow {
  statistics_code: string
  statistics_label: string
  time_code: string
  time_label: string
  time: string
  '1_variable_code': string
  '1_variable_label': string
  '1_variable_attribute_code': string
  '1_variable_attribute_label': string
  '2_variable_code': string
  '2_variable_label': string
  '2_variable_attribute_code': string
  '2_variable_attribute_label': string
  value: number,
  'value_unit': string;
  'value_variable_code': string;
  'value_variable_label': string;
}

function filterEinwohnerCols(): InputDataType[] {
  return Einwohner
    .filter((row: CsvRow) => row['2_variable_attribute_label'] === 'Insgesamt')
    .map((row: CsvRow) => {
      const mappedData: InputDataType = {
        year: row.time.split('-')[0],
        einwohnerAmount: row.value,
      };
      return mappedData;
    });
}

function AutoCardHeader(props: {
  title: React.ReactNode
  year: string | number
  AllYear: string | number
  total: number
}) {
  const einwohnerPerSelectedYear = filterEinwohnerCols().filter(
    (d: InputDataType) => d.year === String(props.year),
  )

  let pkwProEinwohner: number = 0;
  if (einwohnerPerSelectedYear.length > 0) {
    pkwProEinwohner = parseFloat((props.total / einwohnerPerSelectedYear[0].einwohnerAmount).toFixed(3));
  }

  return (
    <>
      <div className="flex flex-wrap justify-start gap-x-4 lg:max-w-[87%]">
        <Title
          as={'h1'}
          className="min-w-fit tracking-tighter xl:text-6xl 2xl:text-7xl"
          font={'normal'}
          variant={'mobility'}
        >
          {props.title} Autos
        </Title>

        <Title as={'subtitle'} color="dark">
          {props.year !== 'Alle Jahre' ? (
            <>
              waren <span className="text-mobility">{props.year}</span> in
              Münster angemeldet.{' '}
              {pkwProEinwohner > 0 ? (
                <>
                  Das waren{' '}
                  <span className="text-mobility">
                    <AnimatedNumber
                      className="inline-block"
                      decimals={3}
                    >
                      {pkwProEinwohner}
                    </AnimatedNumber>{' '}
                    PKW
                  </span>{' '}
                  pro Einwohner*in.{' '}
                </>
              ) : (
                <br />
              )}
              Aufgeteilt auf folgende Antriebsarten:
            </>
          ) : (
            <>
              sind <span className="text-mobility">seit {props.AllYear}</span>{' '}
              in Münster hinzugekommen, aufgeteilt auf folgende Antriebsarten:
            </>
          )}
        </Title>
      </div>
      <Spacer />
    </>
  )
}

export default AutoCardHeader
